<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Maze Bot Explorer</title>
<style>
body{font-family:sans-serif;margin:0;padding:20px;background:#fafafa}
#maze{width:400px;height:400px;border:1px solid #333;position:relative;background:#fff}
.bot-dot{position:absolute;width:6px;height:6px;border-radius:50%;background:red}
#controls{margin-top:10px}
.completed{font-weight:bold;margin-right:20px}
.timer{font-weight:bold}
</style>
</head>
<body>

<div id="maze"></div>
<div id="controls">
  <span class="completed" id="completed">Completed: 0/24</span>
  <span class="timer" id="timer">Timer: 0</span>
  <button id="reset">Reset</button>
</div>

<script>
// ---------- Utility ----------
function mulberry32(a) {
  return function() {
    var t = a += 0x6D2B79F5;
    t = Math.imul(t ^ t >>> 15, t | 1);
    t ^= t + Math.imul(t ^ t >>> 7, t | 61);
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}

function shuffle(array, randFn) {
  for (let i = array.length - 1; i > 0; --i) {
    const j = Math.floor(randFn() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
}

// ---------- Maze ----------
class Maze {
  constructor(rows, cols, randFn) {
    this.rows = rows;
    this.cols = cols;
    this.rand = randFn;
    this.grid = Array.from({length:rows}, (_,r)=>Array.from({length:cols}, (_,c)=>{
      return {n:true,e:true,s:true,w:true};
    }));
    this.generate();
  }
  generate() {
    const stack = [];
    let r=0,c=0;
    stack.push([r,c]);
    while(stack.length){
      [r,c] = stack[stack.length-1];
      const dirs=[];
      if(r>0 && this.grid[r-1][c].s) dirs.push('n');
      if(c< this.cols-1 && this.grid[r][c+1].w) dirs.push('e');
      if(r<this.rows-1 && this.grid[r+1][c].n) dirs.push('s');
      if(c>0 && this.grid[r][c-1].e) dirs.push('w');
      if(dirs.length){
        const dir = dirs[Math.floor(this.rand()*dirs.length)];
        switch(dir){
          case 'n': this.grid[r][c].n=false; this.grid[r-1][c].s=false; r--; break;
          case 'e': this.grid[r][c].e=false; this.grid[r][c+1].w=false; c++; break;
          case 's': this.grid[r][c].s=false; this.grid[r+1][c].n=false; r++; break;
          case 'w': this.grid[r][c].w=false; this.grid[r][c-1].e=false; c--; break;
        }
        stack.push([r,c]);
      }else{
        stack.pop();
      }
    }
  }
  walls(r,c){ return this.grid[r][c];}
}

// ---------- Bot ----------
class Bot {
  constructor(id, maze, spawn, exit, randFn){
    this.id=id;
    this.maze=maze; this.spawn=spawn; this.exit=exit;
    this.pos={r:spawn.r,c:spawn.c};
    this.target=this.pos;
    this.dirOrder=['n','e','s','w'];
    shuffle(this.dirOrder, randFn);
    this.stack=[{r:spawn.r,c:spawn.c}];
    this.visited = new Set();
    this.deadEnds = new Set();
    this.path=[];
    this.finishTick=null;
  }
  step(){
    if(this.finishTick!==null) return; // already finished
    const key=`${this.pos.r},${this.pos.c}`;
    if(!this.visited.has(key)){
      this.visited.add(key);
      this.path.push({r:this.pos.r,c:this.pos.c});
    }
    if(this.pos.r===this.exit.r && this.pos.c===this.exit.c){
      this.finishTick=this.maze.elapsed;
      return;
    }
    const walls = this.maze.walls(this.pos.r,this.pos.c);
    // find next unvisited neighbor
    for(const d of this.dirOrder){
      let nr=this.pos.r, nc=this.pos.c;
      if(d==='n'){if(walls.n) nr--;}
      if(d==='e'){if(walls.e) nc++;}
      if(d==='s'){if(walls.s) nr++;}
      if(d==='w'){if(walls.w) nc--;}
      const nk=`${nr},${nc}`;
      if((d in walls && !walls[d]) && !this.visited.has(nk)){
        this.stack.push({r:nr,c:nc});
        this.pos={r:nr,c:nc};
        return;
      }
    }
    // dead end, backtrack
    const popped=this.stack.pop(); // current cell
    if(this.stack.length===0){ // shouldn't happen before exit
      this.finishTick=this.maze.elapsed; return;
    }
    this.deadEnds.add(`${popped.r},${popped.c}`);
    this.pos=this.stack[this.stack.length-1];
  }
}

// ---------- Game ----------
window.game = {
  size:{rows:15,cols:15},
  spawn:{r:0,c:0},
  exit:{},
  walls(r,c){return this.maze.walls(r,c);},
  elapsed:0,
  bots:[],
  tick(n){
    for(let i=0;i<n;i++){
      if(this.elapsed===this.lastFinish) break;
      for(const bot of this.bots) bot.step();
      this.elapsed++;
      this.updateCompleted();
      if(this.allFinished()) this.freezeTimer();
    }
  },
  reset(seed){
    const rand = mulberry32(seed||Date.now());
    this.maze = new Maze(this.size.rows,this.size.cols,rand);
    this.spawn={r:0,c:0};
    this.exit={r:this.size.rows-1,c:this.size.cols-1};
    this.bots=[];
    for(let i=0;i<24;i++){
      const botRand = mulberry32(seed===undefined?Date.now()+i:i+123456);
      this.bots.push(new Bot(i,this.maze,this.spawn,this.exit,botRand));
    }
    this.elapsed=0;
    this.lastFinish=null;
    this.updateCompleted();
  },
  allFinished(){return this.bots.every(b=>b.finishTick!==null);},
  updateCompleted(){
    const count=this.bots.filter(b=>b.finishTick!==null).length;
    document.getElementById('completed').textContent=`Completed: ${count}/24`;
    document.getElementById('timer').textContent=`Timer: ${this.elapsed}`;
  },
  freezeTimer(){this.lastFinish=this.elapsed;}
};

// ---------- Rendering ----------
const mazeDiv=document.getElementById('maze');
function drawMaze(){
  const {rows,cols}=game.size;
  const cellW=mazeDiv.clientWidth/cols;
  const cellH=mazeDiv.clientHeight/rows;
  for(let r=0;r<rows;r++){
    for(let c=0;c<cols;c++){
      const w=game.walls(r,c);
      if(w.n){
        const line=document.createElement('div');
        line.style.position='absolute';
        line.style.left=c*cellW+'px';line.style.top=(r-1)*cellH+'px';
        line.style.width=cellW+'px';line.style.height='2px';
        line.style.background='#000';
        mazeDiv.appendChild(line);
      }
      if(w.w){
        const line=document.createElement('div');
        line.style.position='absolute';
        line.style.left=(c-1)*cellW+'px';line.style.top=r*cellH+'px';
        line.style.width='2px';line.style.height=cellH+'px';
        line.style.background='#000';
        mazeDiv.appendChild(line);
      }
    }
  }
}
drawMaze();

function renderBots(){
  const {rows,cols}=game.size;
  const cellW=mazeDiv.clientWidth/cols;
  const cellH=mazeDiv.clientHeight/rows;
  game.bots.forEach(bot=>{
    let dot=document.getElementById('bot'+bot.id);
    if(!dot){
      dot=document.createElement('div');
      dot.className='bot-dot';
      dot.id='bot'+bot.id;
      mazeDiv.appendChild(dot);
    }
    const x=(bot.pos.c+0.5)*cellW-3;
    const y=(bot.pos.r+0.5)*cellH-3;
    dot.style.transform=`translate(${x}px,${y}px)`;
  });
}
setInterval(renderBots,30);

// ---------- Controls ----------
document.getElementById('reset').addEventListener('click',()=>{
  game.reset();
});
game.reset();

</script>
</body>
</html>
